CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL,content TEXT NOT NULL,image TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS comments (id SERIAL PRIMARY KEY,post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id INTEGER NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS likes (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL,post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,post_id));
